params.script_inline:
"""The world adapter of a figure: the one cell that speaks the world's lanes, and the only sender into the
agent's turn door.

stdin is {envelope, body, params}; stdout a JSON array of content documents (multi-send). A cell writes no
context: every key a later message needs rides on the hop, and the edge that carries it lifts it into the
context. The agent has ONE caller and runs its turns one at a time, so every turn -- the world's, the phone's,
an interview -- goes through this cell: a turn that arrives while another is open waits in the queue and goes
in when the open turn's `answer` arrives. RAM holds the queue, the open turn, the call book, the phone's replies
of the day with the ones over the cap, the answer rounds already taken and the open extra-tool calls (`resident`);
it is a cache, and a replaced child degrades as the README says (a call finds no open turn, an answer is
matched by its channel).
"""
import json
import sys
import zlib

# The frame of each role (the same honesty in both): truthful about being an AI when asked directly, free
# to decline. It reaches the agent once per child as the pack leaf `instructions.role`: the agent's own door
# writes `instructions.frame` at its boot and affinity's pack is the one leaf `identity`, so either would replace
# it. The identity itself is the agent's own (AIeOS in its affinity).
FRAMES = {
    "human-sim": ("You are an AI living the life of the person your identity describes, in a world you share "
                  "with others: in the first person, as that person would. You are not that person and you never "
                  "claim to be human. If someone asks you directly whether you are an AI, you say truthfully that "
                  "you are. You may decline anything you would not do, in your own words."),
    "npc": ("You are an AI playing the role your identity describes in a game world. You react to the players, "
            "you stay in your role and you follow the state of the game as the world tells it. You never claim to "
            "be human: if someone asks you directly whether you are an AI, you say truthfully that you are. You "
            "may decline anything, in your own words."),
}
SHEETS = {
    "plan": "A new day begins. Plan it with the tools the world offers, then take your first step.",
    "contact": ("Someone is in front of you. Use the world's tools if you need to; what you finally say, in "
                "your own voice, is your answer to them."),
    "event": "Something happened. Decide what you do now and do it with the world's tools.",
}
SHEET_DEFAULT = "Decide what you do now and do it with the world's tools."
END_LINE = "Your turn ends when you stop calling tools; your final text is what you say or think."
# A world turn that ends in text alone moved nothing in the world: the agent asks once more, in the
# same session with the same menu, then ends the turn as it ends (simple-agent@2 `required_tools` in mode `any`, the
# words below as `required_ask`; GH #1311, OR-AG-65). Not on `contact` (the final text is the answer there), not on
# phone or interview turns (they may stay silent), not when the world offered no tool of its own.
ACT_SHEET = ("Your turn ended without an action in the world. Choose one action from the world's tools now and "
             "call it. If you truly do nothing, say so in one sentence.")
# The round id of the agent's follow-up of turn `<id>` (simple-agent@2 door): its client calls carry it.
FOLLOW_SUFFIX = ".follow"
PHONE_SHEET = ("A message arrived on your phone. Your final text is your reply. You may stay silent: end your "
               "turn without text and nothing is sent.")
# The replies on the phone that open a turn, per world day (param `phone_replies_max`): a reply over it opens no
# turn -- two agents that text each other would otherwise talk on forever, one model turn per message.
PHONE_REPLIES_MAX = 4
UNREAD_KEEP = 8
# The base round ids of the phone answers already taken, each with the crc32 of its texts (GH #1292): the colony
# sends a second answer of the same turn under `<round_id>~<ms>~<hash>` (GH #728). The same text again is dropped;
# another text is a correction, read like one on a phone: unread, no turn, no reply spent.
PHONE_ROUNDS_KEEP = 64
INTERVIEW = ("This is an interview, not a move: the world stands still. Answer the question as yourself, from "
             "what you remember, in the first person.")
PHONE_TOOL = {"name": "phone_message", "description": "Send a text message from your phone. It is sent at "
              "once; an answer, if any, comes later as a message of its own.",
              "parameters": {"type": "object", "properties": {"text": {"type": "string",
                                                                      "description": "what you write"}},
                             "required": ["text"]}}
SPEAKERS = {"member": "hp", "game_agent": "game"}
# The hop keys a `calls` of the agent carries and its `tool_result` must bring back (contract V-T): without
# `iter` the result lands in round 0 and the agent never finds its round.
CALL_KEYS = ("turn_id", "session_id", "iter", "channel", "audience_set")


def _obj(v):
    return v if isinstance(v, dict) else {}


def extra_of(params, taken=()):
    """The instance's `extra_tools` (provider schemas): client tools the figure offers on every turn beside the
    world's menu (GH #1311). A name the turn already offers stays the world's (or the phone's)."""
    out = []
    for t in params.get("extra_tools") or []:
        name = _obj(t).get("name") or _obj(_obj(t).get("function")).get("name")
        if name and name not in taken and name not in [n for n, _ in out]:
            out.append((str(name), t))
    return out


def with_extra(params, item):
    """`item` with the extra tools on its menu, their names remembered: an extra call is no action in the world.
    Without an entry the item is returned unchanged, byte for byte."""
    extra = extra_of(params, offered(item))
    if not extra:
        return item
    item["tools"] = list(item.get("tools") or []) + [t for _, t in extra]
    item["extra"] = [n for n, _ in extra]
    return item


def _text(t):
    return t if isinstance(t, str) else json.dumps(t, ensure_ascii=False)


def rim(route, slot):
    """One message on the figure's rim: the body slot of the lane's name. `figure_rim` tells the hive's door
    that this message leaves, so the door edge of the same lane never takes it back in."""
    return {"header": {"route": route, "figure_rim": "out"}, route: slot, "messages": []}


def ids(params):
    return str(params.get("figure_id") or "figure"), str(params.get("world_id") or "world")


def audience(params):
    return json.dumps(["member:%s" % ids(params)[0]])


def phone_of(params):
    p = _obj(params.get("phone"))
    speaker = p.get("speaker") or "member"
    return {"enabled": p.get("enabled") in (True, "1", "true") and params.get("role") == "human-sim",
            "speaker": speaker if speaker in SPEAKERS else "member",
            "contact": str(p.get("contact") or "your contact")}


def chat_id(params):
    fid, wid = ids(params)
    return "%s:%s:%s" % (SPEAKERS[phone_of(params)["speaker"]], wid, fid)


def keep_id(st, value):
    """Remember the world's own id under its string form (hop values are strings) and return that form."""
    key = str(value)
    book = st.setdefault("tid", {})
    book.pop(key, None)
    book[key] = value
    while len(book) > 128:
        book.pop(next(iter(book)))
    return key


def world_id_of(st, key):
    """The id as the world sent it: an int comes back an int."""
    return (st.get("tid") or {}).get(str(key), key) if key is not None else None


def frame_pack(params):
    return {"header": {"route": "in_pack"}, "system": {"instructions": {"role": {"text": FRAMES[params["role"]]}}},
            "messages": []}


def boot(st, params):
    """The role's frame, once per child: the same bytes over the same leaf, so a replaced child repeats it."""
    if st.get("framed"):
        return []
    st["framed"] = True
    return [frame_pack(params)]


def use_session(st, day, session):
    used = st.setdefault("sessions", {}).setdefault(str(day), [])
    if session not in used:
        used.append(session)


def turn_doc(params, item):
    """One turn into the agent's door (contract V-T): the hop keys the door lifts, the turn's text, the
    client tools of exactly this turn."""
    head = {"route": "turn", "turn_id": item["key"], "channel": item["channel"], "session_id": item["session"],
            "audience_set": audience(params), "figure_kind": item["kind"], "figure_day": str(item["day"])}
    doc = {"header": head, "messages": [{"origin": "user", "type": "text", "text": item["text"]}],
           "tools": item.get("tools") or []}
    # The action a world turn owes: one call of the world's menu or of `phone_message` -- an extra tool
    # is no action. The agent's door checks it and asks once (mode `any`: one tool is enough, no follow-up after a
    # capped turn, the first text stays); its follow-up requires a call of its first brain call (#1292).
    required = required_of(item)
    if required:
        head["required_tools"] = json.dumps(required)
        head["required_mode"] = "any"
        head["required_ask"] = ACT_SHEET
    return doc


def required_of(item):
    """The tools of which a world turn owes one call: none on contact, phone and interview turns, none when the
    world offered no tool of its own."""
    if item.get("kind") != "world" or item.get("world_kind") == "contact":
        return []
    acts = [n for n in offered(item) if n not in (item.get("extra") or [])]
    return acts if any(n != PHONE_TOOL["name"] for n in acts) else []


def owns(item, turn_id):
    """A round of the open turn: the turn itself or the agent's follow-up of it."""
    return turn_id in (item["key"], item["key"] + FOLLOW_SUFFIX)


def close_docs(st, params, day):
    sessions = list((st.get("sessions") or {}).pop(str(day), []))
    if "day-%s" % day not in sessions:
        sessions.insert(0, "day-%s" % day)
    st.setdefault("nights", {})[str(day)] = {"left": list(sessions), "ok": True, "added": 0, "closed": 0}
    return [{"header": {"route": "close", "session_id": s, "channel": "world:%s" % ids(params)[1],
                        "audience_set": audience(params), "figure_kind": "night", "figure_day": str(day)},
             "close": {"session_id": s}, "messages": []} for s in sessions]


def pump(st, params):
    """Start the next queued turn when none is open. A night waits behind the open turn like a turn, but opens
    nothing: its closes leave and the queue goes on."""
    out = []
    queue = st.setdefault("queue", [])
    while st.get("open") is None and queue:
        item = queue.pop(0)
        if item["kind"] == "night":
            out += close_docs(st, params, item["day"])
            continue
        st["open"] = item
        use_session(st, item["day"], item["session"])
        out.append(turn_doc(params, item))
    return out


def refuse_role(params, body, route):
    """A figure whose role is neither frame refuses every turn loudly: a turn without its frame is a figure
    that might claim to be human."""
    out = [rim("error", {"error_code": "role_unknown", "kind": str(params.get("role") or "")})]
    if route == "obs":
        out.append(rim("intent", {"turn_id": _obj(body.get("obs")).get("turn_id"), "never": True}))
    elif route == "interview":
        q = _obj(body.get("interview"))
        out.append(rim("interview", {"question_id": q.get("question_id"), "answer": None,
                                     "error": "role_unknown", "error_code": "role_unknown"}))
    return out


def on_obs(st, params, body):
    o = _obj(body.get("obs"))
    day = o.get("day")
    kind = str(o.get("kind") or "event")
    if not isinstance(day, int) or isinstance(day, bool):
        # Without its day a turn would run in a session no night ever closes: refused, never a silent `day-0`.
        return [rim("error", {"error_code": "obs_without_day", "turn_id": o.get("turn_id"), "kind": kind}),
                rim("intent", {"turn_id": o.get("turn_id"), "never": True})]
    key = keep_id(st, o.get("turn_id"))
    seen = st.setdefault("seen", [])
    if key in seen:
        return [rim("error", {"error_code": "duplicate_turn", "turn_id": o.get("turn_id"), "kind": kind})]
    st["seen"] = (seen + [key])[-128:]
    st["day"] = day
    # The world's own clock (ISO-8601 game time, optional): the phone stamps it on what leaves, so the other
    # side replays the message at the time it happened in the world. Without one: no stamp at all.
    at = o.get("at")
    if isinstance(at, str) and at.strip():
        st["at"] = at.strip()
    else:
        st.pop("at", None)
    tools = [t for t in o.get("tools") or [] if isinstance(t, dict) and t.get("name")]
    if phone_of(params)["enabled"] and not any(t["name"] == PHONE_TOOL["name"] for t in tools):
        tools.append(PHONE_TOOL)
    parts = [SHEETS.get(kind, SHEET_DEFAULT), END_LINE]
    if o.get("deadline_ms"):
        parts.append("The world gives you %s ms for this turn." % o["deadline_ms"])
    parts.append(_text(o.get("text", "")))
    unread = st.pop("unread", None)
    if unread:
        parts.append("Messages from %s reached your phone while you could not answer them:\n%s"
                     % (phone_of(params)["contact"], "\n".join("- %s" % u for u in unread)))
    st.setdefault("queue", []).append(with_extra(params, {
        "kind": "world", "key": key, "day": day, "world_kind": kind, "channel": "world:%s" % ids(params)[1],
        "session": "day-%s" % day, "text": "\n\n".join(parts), "tools": tools}))
    return pump(st, params)


def on_interview(st, params, body):
    q = _obj(body.get("interview"))
    qid = keep_id(st, q.get("question_id"))
    day = st.get("day") if st.get("day") is not None else 0
    text = "%s\n\n%s" % (INTERVIEW, _text(q.get("question", "")))
    st.setdefault("queue", []).append(with_extra(params, {
        "kind": "interview", "key": "interview-%s" % qid, "qid": qid, "day": day,
        "channel": "interview:%s" % ids(params)[1], "session": "interview-%s" % day, "text": text, "tools": []}))
    return pump(st, params)


def replies_max(params):
    v = params.get("phone_replies_max", PHONE_REPLIES_MAX)
    try:
        return max(0, int(v))
    except (TypeError, ValueError):
        return PHONE_REPLIES_MAX


def on_phone_in(st, params, hop, body):
    """An answer on the figure's own human channel, handed in by `phone`: a phone turn, queued like any --
    up to `phone_replies_max` a world day. Over it the answer opens no turn: it leaves on the rim as
    `phone_capped` (the world's journal) and waits, unanswered, for the figure's next world turn (its memory).
    A second answer of a round already taken: the same text is dropped, another one waits unread, uncounted."""
    m = _obj(body.get("phone_in"))
    channel = str(m.get("channel") or "")
    if channel != chat_id(params):  # none is no proof of this channel (V-H)
        return [rim("error", {"error_code": "foreign_channel", "kind": "phone", "channel": channel})]
    text = _text(m.get("text") or "").strip()
    if not text:
        return []
    round_id = str(m.get("round_id") or "")
    if round_id:
        crc = zlib.crc32(text.encode())
        rounds = [r if isinstance(r, list) else [r, []] for r in st.get("phone_rounds") or []]
        seen = next((r for r in rounds if r[0] == round_id), None)
        if seen is not None:
            if crc not in seen[1]:
                seen[1].append(crc)
                st["phone_rounds"] = rounds
                st["unread"] = (list(st.get("unread") or []) + [text])[-UNREAD_KEEP:]
            return []
        st["phone_rounds"] = (rounds + [[round_id, [crc]]])[-PHONE_ROUNDS_KEEP:]
    day = st.get("day") if st.get("day") is not None else 0
    count = _obj(st.get("phone_replies"))
    n = int(count.get("n") or 0) if count.get("day") == day else 0
    cap = replies_max(params)
    if n >= cap:
        st["unread"] = (list(st.get("unread") or []) + [text])[-UNREAD_KEEP:]
        return [rim("phone_capped", {"day": day, "channel": channel, "text": text, "replies": n, "max": cap})]
    st["phone_replies"] = {"day": day, "n": n + 1}
    st["phone_seq"] = int(st.get("phone_seq") or 0) + 1
    key = "phone-%s-%s-%d" % (day, zlib.crc32(text.encode()) % 100000, st["phone_seq"])
    full = "%s\n\nMessage from %s: %s" % (PHONE_SHEET, phone_of(params)["contact"], text)
    st.setdefault("queue", []).append(with_extra(params, {
        "kind": "phone", "key": key, "day": day, "channel": "phone:%s" % ids(params)[1],
        "session": "phone-%s" % day, "text": full, "tools": []}))
    return pump(st, params)


def on_night(st, params, body):
    day = _obj(body.get("night")).get("day")
    st.setdefault("queue", []).append({"kind": "night", "day": day})
    return pump(st, params)


def on_mandate(body):
    m = _obj(body.get("mandate"))
    if m.get("action") == "stop":
        text = "You have no standing order."
    else:
        text = "Your owner gave you a standing order: %s" % _text(m.get("note") or "")
        if m.get("frame"):
            text += " Within: %s." % _text(m["frame"])
        if m.get("until"):
            text += " It stands until %s." % _text(m["until"])
    return [{"header": {"route": "in_pack"}, "system": {"instructions": {"mandate": {"text": text}}},
             "messages": []}]


def call_of(hop, body):
    """Name and arguments of one client call: the body slot `calls`, else the tool_call turn."""
    slot = _obj(body.get("calls"))
    name = hop.get("tool_name") or slot.get("name") or slot.get("tool")
    args = slot.get("arguments", slot.get("args"))
    if args is None:
        for t in body.get("messages") or []:
            if _obj(t).get("type") == "tool_call":
                try:
                    fn = _obj(json.loads(t.get("text") or ""))
                except ValueError:
                    fn = {}
                name = name or fn.get("name")
                args = fn.get("arguments")
                break
    if isinstance(args, str):
        try:
            args = json.loads(args)
        except ValueError:
            pass
    return str(name or ""), (args if args is not None else {})


def tool_result(keys, call_id, content, is_error=False, code=None):
    head = {"route": "tool_result"}
    head.update({k: keys[k] for k in CALL_KEYS if k in keys})
    slot = {"id": call_id, "content": _text(content), "is_error": bool(is_error)}
    if code:
        slot["error_code"] = code
    return {"header": head, "tool_result": slot, "messages": []}


def offered(item):
    return [str(_obj(t).get("name")) for t in item.get("tools") or [] if _obj(t).get("name")]


def on_calls(st, params, hop, body):
    keys = {k: str(hop[k]) for k in CALL_KEYS if k in hop}
    call_id = str(hop.get("tool_call_id") or "")
    name, args = call_of(hop, body)
    open_ = st.get("open")
    if open_ is None or not owns(open_, keys.get("turn_id")):
        return [tool_result(keys, call_id, "no open turn takes %s now" % (name or "this call"), True)]
    if name not in offered(open_):
        # The menu of THIS turn is the whole menu: a phone or interview turn offers nothing, a world turn what
        # its `obs` offered (and `phone_message` when the phone is enabled).
        return [tool_result(keys, call_id, {"error_code": "tool_not_offered", "tool": name,
                                            "offered": offered(open_)}, True, "tool_not_offered")]
    if name in (open_.get("extra") or []):
        # An extra tool (GH #1311) leaves the figure on its rim as `calls`; its result comes back on the rim lane
        # `tool_result` and goes into the round it was asked in. It moves nothing in the world: no action.
        st.setdefault("extra_calls", {})[call_id] = keys
        head = {"route": "calls", "figure_rim": "out", "tool_name": name, "tool_call_id": call_id}
        head.update(keys)
        return [{"header": head, "calls": {"id": call_id, "name": name, "arguments": args}, "messages": []}]
    if name == PHONE_TOOL["name"]:
        text = _text(_obj(args).get("text") or "").strip()
        if not phone_of(params)["enabled"]:
            return [tool_result(keys, call_id, "phone_message is not available to you", True)]
        if not text:
            return [tool_result(keys, call_id, "empty message", True)]
        # Texting is asynchronous: the message leaves through `phone`, and the turn goes on at once.
        return [phone_out(params, text, st.get("at")), tool_result(keys, call_id, {"status": "sent"})]
    st.setdefault("calls", {})[call_id] = keys
    return [rim("call", {"turn_id": world_id_of(st, open_["key"]), "call_id": call_id, "tool": name,
                         "args": args})]


def on_call_result(st, params, body):
    r = _obj(body.get("call_result"))
    call_id = str(r.get("call_id") or "")
    keys = (st.get("calls") or {}).pop(call_id, None)
    if keys is None:
        # A result nobody waits for (its turn ended, or a replaced child): the agent's guard already answered.
        return [rim("error", {"error_code": "call_unknown", "turn_id": r.get("turn_id"), "kind": "call"})]
    result = r.get("result")
    failed = isinstance(result, dict) and result.get("accepted") is False
    return [tool_result(keys, call_id, result, failed)]


def on_extra_result(st, body):
    """The result of one extra tool's `calls`, from the rim: into the round of the call, or named when nobody waits."""
    r = _obj(body.get("tool_result"))
    call_id = str(r.get("id") or "")
    keys = (st.get("extra_calls") or {}).pop(call_id, None)
    if keys is None:
        return [rim("error", {"error_code": "call_unknown", "turn_id": None, "kind": "tool_result"})]
    return [tool_result(keys, call_id, r.get("content", ""), r.get("is_error") is True)]


def phone_out(params, text, at=None):
    ph = phone_of(params)
    head = {"route": "phone_out", "phone_chat_id": chat_id(params)}
    if ph["speaker"] == "game_agent":
        head["phone_speaker"] = "game_agent"
    if at:
        head["phone_at"] = at
    return {"header": head, "phone_out": {"text": text}, "messages": []}


def answer_of(hop, body):
    slot = _obj(body.get("answer"))
    text = slot.get("text")
    if text is None:
        text = "\n".join(t.get("text") or "" for t in body.get("messages") or []
                         if _obj(t).get("type", "text") == "text")
    code = slot.get("error_code") or hop.get("error_code") or _obj(slot.get("error")).get("error_code") \
        or (slot.get("error") if isinstance(slot.get("error"), str) else None)
    failed = bool(code) or bool(slot.get("error")) or hop.get("finish_reason") == "error"
    return str(slot.get("turn_id") or hop.get("turn_id") or ""), _text(text or "").strip(), failed, code


def item_for(st, params, key, channel):
    """The open turn the answer belongs to; after a replaced child, a stand-in built from the channel."""
    open_ = st.get("open")
    if open_ is not None and (not key or open_["key"] == key):
        st["open"] = None
        return open_
    _, wid = ids(params)
    if channel == "phone:%s" % wid:
        return {"kind": "phone", "key": key}
    if channel == "interview:%s" % wid or key.startswith("interview-"):
        return {"kind": "interview", "key": key, "qid": key[len("interview-"):]}
    return {"kind": "world", "key": key}


def finish(st, params, item, text, failed, code):
    kind = item["kind"]
    # The open calls of the turn go with it -- of every kind: extra tools ride on phone and interview turns too.
    for book in ("calls", "extra_calls"):
        for cid in [c for c, k in (st.get(book) or {}).items() if owns(item, k.get("turn_id"))]:
            st[book].pop(cid, None)
    if kind == "world":
        tid = world_id_of(st, item["key"])
        if failed:
            return [rim("error", {"error_code": code or "turn_failed", "turn_id": tid, "kind": "world"}),
                    rim("intent", {"turn_id": tid, "never": True})]
        return [rim("intent", {"turn_id": tid, "done": True, "text": text})]
    if kind == "interview":
        qid = world_id_of(st, item.get("qid"))
        if failed:
            return [rim("interview", {"question_id": qid, "answer": None, "error": code or "turn_failed",
                                      "error_code": code or "turn_failed"})]
        return [rim("interview", {"question_id": qid, "answer": text})]
    if failed:
        return [rim("error", {"error_code": code or "turn_failed", "turn_id": item["key"], "kind": "phone"})]
    # The reply of a phone turn is its final text; an empty one is no reply.
    return [phone_out(params, text, st.get("at"))] if text else []


def on_answer(st, params, hop, body):
    key, text, failed, code = answer_of(hop, body)
    item = item_for(st, params, key, str(hop.get("channel") or ""))
    return finish(st, params, item, text, failed, code) + pump(st, params)


def on_agent_error(st, params, hop, body):
    """An error of the agent: on the rim always; when it names the open turn, that turn ends failed."""
    e = _obj(body.get("error"))
    code = e.get("error_code") or hop.get("error_code") or "agent_error"
    key = str(e.get("turn_id") or hop.get("turn_id") or "")
    open_ = st.get("open")
    if key and open_ is not None and open_["key"] == key:
        st["open"] = None
        return finish(st, params, open_, "", True, code) + pump(st, params)
    return [rim("error", {"error_code": code, "turn_id": key or None, "kind": "agent"})]


def on_close_report(st, body, hop):
    r = _obj(body.get("close_report"))
    session = str(r.get("session_id") or hop.get("session_id") or "")
    for day, night in list((st.get("nights") or {}).items()):
        if session in night["left"]:
            night["left"].remove(session)
            night["ok"] = night["ok"] and r.get("ok", True) is not False
            night["added"] += int(r.get("added") or 0)
            night["closed"] += int(r.get("closed") or 0)
            if night["left"]:
                return []
            st["nights"].pop(day)
            d = int(day) if day.lstrip("-").isdigit() else day
            # The receipt only after the last close report: each report triggers the agent's dream; the world does not wait for it.
            return [rim("night", {"day": d, "ok": night["ok"], "added": night["added"],
                                  "closed": night["closed"]})]
    return []


def on_message(doc, st):
    header = _obj(_obj(doc.get("envelope")).get("header"))
    hop, body = _obj(header.get("hop")), _obj(doc.get("body"))
    params = _obj(doc.get("params"))
    route = hop.get("route")
    if route in ("obs", "interview", "night", "phone_in", "mandate") and params.get("role") not in FRAMES:
        return refuse_role(params, body, route)
    handlers = {
        "obs": lambda: on_obs(st, params, body),
        "interview": lambda: on_interview(st, params, body),
        "night": lambda: on_night(st, params, body),
        "phone_in": lambda: on_phone_in(st, params, hop, body),
        "mandate": lambda: on_mandate(body),
        "call_result": lambda: on_call_result(st, params, body),
        "calls": lambda: on_calls(st, params, hop, body),
        "answer": lambda: on_answer(st, params, hop, body),
        "error": lambda: on_agent_error(st, params, hop, body),
        "close_report": lambda: on_close_report(st, body, hop),
        "tool_result": lambda: on_extra_result(st, body),
    }
    if route not in handlers:
        # Everything else that reaches this cell is drained on purpose (acknowledgements of the agent).
        return []
    out = handlers[route]()
    if params.get("role") in FRAMES and route in ("obs", "interview", "night", "phone_in", "mandate"):
        out = boot(st, params) + out
    return out


if __name__ == "__main__":
    if "STATE" not in globals():
        STATE = {}
    sys.stdout.write(json.dumps(on_message(json.load(sys.stdin), STATE)))
